SELECT ticket_id, status
FROM support_tickets
WHERE payload ->> 'channel' = 'chat';

SELECT account_id, plan_id
FROM (
    SELECT s.account_id, s.plan_id,
           ROW_NUMBER() OVER (
               PARTITION BY s.account_id
               ORDER BY s.starts_on DESC, s.subscription_id DESC
           ) AS rn
    FROM subscriptions AS s
) AS ranked
WHERE rn = 1;

SELECT da.invoice_id, MAX(da.attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts AS da
GROUP BY da.invoice_id;

SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alerts
FROM alerts
GROUP BY customer_id;

SELECT product_id, on_hand_qty
FROM (
    SELECT product_id, on_hand_qty,
           ROW_NUMBER() OVER (
               PARTITION BY product_id
               ORDER BY snapshot_at DESC, snapshot_id DESC
           ) AS rn
    FROM inventory_snapshots
) AS latest
WHERE rn = 1;
